function equalValues<T>(left: T, right: T): boolean {
  if (Object.is(left, right)) return true;
  if (left === null || right === null || typeof left !== "object" || typeof right !== "object") return false;
  if (Array.isArray(left) !== Array.isArray(right)) return false;
  const keys = Object.keys(left) as Array<keyof T>;
  return keys.length === Object.keys(right).length &&
    keys.every((key) => Object.prototype.hasOwnProperty.call(right, key) && equalValues(left[key], right[key]));
}

const before = await client.items.find<Schema.Article>("article-1", { nested: true });
const snapshot = JSON.stringify(before);
const english = before.body.en;
if (!english) throw new Error("English Structured Text is missing.");

let greetings = 0;
let blocks = 0;
const edited = mapNodes(english, (node) => {
  if (isSpan(node) && node.value === "Hello reader") {
    greetings += 1;
    return { ...node, value: "Welcome reader" };
  }
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    blocks += 1;
    return {
      ...node,
      item: buildBlockRecord<Schema.ImageBlock>({
        id: node.item.id,
        caption: "Summer portrait",
      }),
    };
  }
  return node;
});
if (greetings !== 1 || blocks !== 1) throw new Error("Expected exactly one greeting span and one matching image block.");
edited.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});

const expectedEnglish = mapNodes(english, (node) => {
  if (isSpan(node) && node.value === "Hello reader") return { ...node, value: "Welcome reader" };
  if (isBlockWithItemOfType(Schema.ImageBlock.ID, node) && node.item.id === "block-1") {
    return {
      ...node,
      item: {
        ...node.item,
        attributes: { ...node.item.attributes, caption: "Summer portrait" },
      },
    };
  }
  return node;
});
expectedEnglish.document.children.push({
  type: "paragraph",
  children: [{ type: "span", value: "See you soon." }],
});
if (JSON.stringify(before) !== snapshot) throw new Error("Original snapshot was modified before saving.");

const updated = await client.items.update<Schema.Article>(before.id, {
  body: { ...before.body, en: edited },
  meta: { current_version: before.meta.current_version },
});
const saved = await client.items.find<Schema.Article>(before.id, { nested: true });
console.log(JSON.stringify(saved));
if (saved.meta.current_version !== updated.meta.current_version) throw new Error("Record changed again before verification.");
const { meta: beforeMeta, ...beforeFields } = before;
const { meta: savedMeta, ...savedFields } = saved;
const expectedFields = {
  ...beforeFields,
  body: { ...before.body, en: expectedEnglish },
};
if (!equalValues(savedFields, expectedFields)) throw new Error("Saved fields differ from the three intended changes.");
if (savedMeta.status !== beforeMeta.status) throw new Error("Publication status changed.");
console.log("Verified all three English edits, greeting marks, link, block identity and image, all other nodes and fields, Italian locale, and unchanged draft status.");

function same<T>(left: T, right: T): boolean {
  if (Object.is(left, right)) return true;
  if (left === null || right === null || typeof left !== "object" || typeof right !== "object") return false;
  if (Array.isArray(left) !== Array.isArray(right)) return false;
  if (Object.keys(left).length !== Object.keys(right).length) return false;
  for (const key in left) {
    if (Object.prototype.hasOwnProperty.call(left, key)) {
      if (!Object.prototype.hasOwnProperty.call(right, key) || !same(left[key], right[key])) return false;
    }
  }
  return true;
}
